function show(v){stop();view=v;document.querySelectorAll('.view').forEach(e=>e.classList.add('hidden'));$('#'+v+'-view').classList.remove('hidden');document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='studio')renderStats();if(v==='saved')renderSaved()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>show(b.dataset.view));document.querySelector('.brand').onclick=e=>{e.preventDefault();show('feed')};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{stop();filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));cards.forEach(c=>c.el.classList.toggle('hidden',filter!=='All'&&c.g.genre!==filter));feed.scrollTop=0});
function visibleCards(){return [...feed.querySelectorAll('.game-card')].map(el=>cards.get(el.dataset.id)).filter(c=>!c.el.classList.contains('hidden'))}function current(){const cs=visibleCards();return cs.reduce((a,c)=>Math.abs(c.el.offsetTop-feed.offsetTop-feed.scrollTop)<Math.abs(a.el.offsetTop-feed.offsetTop-feed.scrollTop)?c:a,cs[0])}function next(){stop();const cs=visibleCards(),i=cs.indexOf(current());cs[(i+1)%cs.length].el.scrollIntoView({behavior:'smooth',block:'start'})}feed.addEventListener('scroll',()=>{if(active&&current()!==active)stop()},{passive:true});feed.addEventListener('keydown',e=>{if(active||e.target.matches('input,textarea,select'))return;if(e.key==='ArrowDown'){e.preventDefault();next()}if(e.key==='ArrowUp'){e.preventDefault();const cs=visibleCards(),i=cs.indexOf(current());cs[(i+cs.length-1)%cs.length].el.scrollIntoView({behavior:'smooth',block:'start'})}});
function start(id){stop();const c=cards.get(id);if(!c)throw Error('Unknown game');if(view!=='feed')show('feed');if(c.el.classList.contains('hidden')){filter='All';document.querySelector('[data-filter="All"]').click()}c.el.scrollIntoView({block:'start'});active=c;if(c.g.upload){startUpload(c);return}c.state={elapsed:0,score:0,x:480,lane:1,objects:[],bullets:[],spawn:0,shot:0,target:Math.floor(Math.random()*4),tiles:Array.from({length:12},()=>Math.floor(Math.random()*4))};c.el.classList.add('playing');c.el.querySelector('.play').textContent='Pause demo';c.el.querySelector('.instruction').textContent=c.g.instruction;c.el.querySelector('.end-screen')?.remove();stats[id].starts++;feed.focus({preventScroll:true})}
function stop(){if(!active)return;active.el.querySelector('.upload-player')?.remove();active.el.classList.remove('playing');active.el.querySelector('.play').textContent='▶ Play again';active.el.querySelector('.instruction').textContent='';active.el.querySelector('.score').textContent='';active=null}
function end(){const c=active,score=c.state.score;stop();const panel=document.createElement('div');panel.className='end-screen';const h=document.createElement('h3');h.textContent='Good game.';const p=document.createElement('p');p.textContent=`${score} points · One more round?`;const b=document.createElement('button');b.className='primary';b.textContent='Play again';b.onclick=()=>start(c.g.id);panel.append(h,p,b);c.el.append(panel)}
function pointer(c,e,down){if(c.g.upload)return;const box=c.canvas.getBoundingClientRect(),x=(e.clientX-box.left)/box.width*960,y=(e.clientY-box.top)/box.height*540,s=c.state;if(c.g.kind===0)s.x=Math.max(28,Math.min(932,x));if(c.g.kind===1&&down)s.lane=Math.max(0,Math.min(2,s.lane+(x<480?-1:1)));if(c.g.kind===2&&down){const col=Math.floor((x-250)/120),row=Math.floor((y-142)/92);if(col<0||col>3||row<0||row>2)return;const n=row*4+col;if(s.tiles[n]===s.target){s.score+=10;s.target=Math.floor(Math.random()*4);s.tiles=Array.from({length:12},()=>Math.floor(Math.random()*4));s.tiles[Math.floor(Math.random()*12)]=s.target}else s.score=Math.max(0,s.score-5)}}
window.addEventListener('keydown',e=>{if(!active||active.g.upload||e.target.matches('input,select,textarea')||document.querySelector('dialog[open]'))return;if(['ArrowLeft','ArrowRight','Escape',' '].includes(e.key))e.preventDefault();const s=active.state;if(e.key==='Escape'||e.key===' ')stop();else if(e.key==='ArrowLeft'){s.x=Math.max(28,s.x-40);s.lane=Math.max(0,s.lane-1)}else if(e.key==='ArrowRight'){s.x=Math.min(932,s.x+40);s.lane=Math.min(2,s.lane+1)}else if(active.g.kind===2&&/^[1-9]$/.test(e.key)){const n=Number(e.key)-1;if(s.tiles[n]===s.target){s.score+=10;s.target=(s.target+1)%4;s.tiles[n]=s.target}}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
const colors=['#d5ff5f','#a797ff','#67dfed','#ff916d'];function rect(ctx,x,y,w,h,color,r=8){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}function ship(ctx,x,y,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x,y-25);ctx.lineTo(x+19,y+21);ctx.lineTo(x,y+10);ctx.lineTo(x-19,y+21);ctx.closePath();ctx.fill();rect(ctx,x-5,y+23,10,18,'#fff8',3)}
