  if(s){s.spawn+=dt;if(s.spawn>.7){s.objects.push({lane:Math.floor(Math.random()*3),y:20});s.spawn=0}s.objects.forEach(o=>{o.y+=dt*250;rect(ctx,355+o.lane*160-20,o.y,40,60,'#ff916d',8);if(o.y>440&&!o.counted){s.score+=10;o.counted=true}if(o.lane===s.lane&&o.y>315&&o.y<440){s.score=Math.max(0,s.score-15);o.y=650}});s.objects=s.objects.filter(o=>o.y<580)}
